const BOTS = ["ai chat","chat ai","chat al"];
const EXCLUDE = [];   // TODO: Prince + the MadeEA team contact ids (must match the setter's list)
const data = $input.first().json;
const convs = data.conversations || [];
const localNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/London' }));
  const dow = localNow.getDay();
  const localHour = localNow.getHours();
const DAYS = [0,1,2,3,4,5,6], START = 0, END = 24;   // mirrors the setter's CONFIG (currently 24/7)
const daytime = DAYS.includes(dow) && localHour >= START && localHour < END;
  if (!daytime) return [];   // hard stop: nothing runs outside the window above
const out = [];
for (const c of convs) {
  if (c.lastMessageType !== 'TYPE_INSTAGRAM') continue;
  if (c.lastMessageDirection !== 'outbound') continue;
  if (EXCLUDE.includes(c.contactId)) continue;
  const name = (c.contactName || c.fullName || '').toLowerCase();
  if (BOTS.some(b => name.includes(b))) continue;
  if (Date.now() - (c.lastMessageDate || 0) > 30*3600000) continue;   // keep recent (covers nudged-then-window-closed)
  out.push({ json: { conversationId: c.id, contactId: c.contactId,
    contactName: c.contactName || c.fullName || c.id, convLastMsgDate: c.lastMessageDate, daytime } });
}
return out;

function hasPlaceholder(s) {
  const t = String(s);
  if (/\[[^\]]*\]|\{\{|\}\}|<[a-z_]+>/i.test(t)) return true;
  if (/\b(your business name|business name here|their name|insert |name here|first name)\b/i.test(t)) return true;
  return false;
}
function oneMarker(s) {
  const RE = /([\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B00}-\u{2BFF}]\u{FE0F}?|:-?\)|:-?\(|;-?\)|:D)/gu;
  let n = 0;
  return s.replace(RE, m => (++n === 1 ? m : '')).replace(/ {2,}/g, ' ').replace(/\s+([.!?,])/g, '$1').trim();
}

function stripControl(s) {
  s = s.replace(/<(\w+:[\w:]+)>[\s\S]*?<\/\1>/g, '');   // paired control blocks like <budget:token_budget>..</budget:token_budget>
  s = s.replace(/<budget:[\s\S]*$/i, '');               // any trailing budget tag (closed or not)
  s = s.replace(/<\/?\w+:[\w:.\-]*[^>]*>/g, '');         // leftover namespaced/control tags
  return s.replace(/\s*[\u2014\u2013]\s*/g, ', ').replace(/\s*\n+\s*/g, ' ').replace(/[ \t]{2,}/g, ' ').trim();
}

// Same two MadeEA-specific guards as the setter. A nudge is still a message
// under the brand's handle, so it gets the same category and Fact Pack checks.
function isBannedCategory(s) {
  const t = String(s).toLowerCase();
  if (/\bv\.?a\.?s?\b/.test(t) && !/\bvalue\b/.test(t)) return true;
  if (/\bvirtual assistants?\b/.test(t)) return true;
  if (/\b(outsourc|offshor)(e|ed|ing)\b/.test(t)) return true;
  return false;
}
function isUnapprovedPrice(s) {
  const APPROVED = /^(3,?000|3k|2,?250)$/i;
  const nums = String(s).match(/(?:\$|usd\s*|\u00a3|\u20ac)\s?([\d,]+(?:\.\d+)?k?)/gi) || [];
  for (const n of nums) {
    const bare = n.replace(/[^\d,.k]/gi, '');
    if (!APPROVED.test(bare)) return true;
  }
  if (/\b\d{1,2}\s?%\s?(off|discount)\b/i.test(String(s))) return true;
  return false;
}
// SOP non-negotiable #4, applied to nudges too: a chase that runs long reads as
// desperate, which is the one tone the SOP never wants.
function isTooLong(s) {
  const sentences = String(s).split(/(?<=[.!?])\s+/).filter(x => x.trim().length > 1);
  return sentences.length > 2;
}

const reqs = $('Decide').all().filter(it => it.json.action === 'nudge');   // align with nudges only
const ors = $input.all();
const out = [];
for (let i = 0; i < ors.length; i++) {
  const ctx = reqs[i].json;
  const r = ors[i].json;
  let draft = (Array.isArray(r.content) ? r.content.filter(b => b && b.type === 'text').map(b => b.text).join('') : '').trim();
  if (!draft) continue;
    if (/^<SKIP/i.test(draft)) continue;
    draft = oneMarker(stripControl(draft));
    if (!draft) continue;
    if (hasPlaceholder(draft)) continue;      // never ship a [FIRST NAME]
    if (isBannedCategory(draft)) continue;    // never say VA / outsourcing / offshore
    if (isUnapprovedPrice(draft)) continue;   // only $3,000 and $2,250 exist
    if (isTooLong(draft)) continue;           // max 2 sentences
  out.push({ json: { conversationId: ctx.conversationId, contactId: ctx.contactId, contactName: ctx.contactName,
    lastInboundMs: ctx.lastInboundMs, ageH: ctx.ageH, convLastMsgDate: ctx.convLastMsgDate, dryRun: ctx.dryRun, message: draft } });
}
return out;

const sd = $getWorkflowStaticData('global'); sd.nudged = sd.nudged || {};
const out = [];
for (const it of $input.all()) { const j = it.json; sd.nudged[j.conversationId] = j.lastInboundMs; out.push({ json: j }); }
return out;

// Pre-nudge safety: only nudge if nobody (the lead or the MadeEA team) messaged since we decided.
const recheck = $input.all();
const items = $('Extract Follow-up').all();   // nudge items, 1:1 with recheck (live: all reach send branch)
const out = [];
for (let i = 0; i < recheck.length; i++) {
  const conv = recheck[i].json.conversation || recheck[i].json;
  const ctx = items[i] ? items[i].json : null;
  if (!ctx) continue;
  const lmd = conv.lastMessageDate;
  const curMs = (lmd && typeof lmd === 'object')
    ? (lmd.seconds * 1000 + Math.floor((lmd.nanoseconds || 0) / 1e6))
    : Number(lmd);
  const leadReplied = conv.lastMessageDirection === 'inbound';                                   // lead came back -> the setter handles it
  const newerActivity = curMs && ctx.convLastMsgDate && curMs > Number(ctx.convLastMsgDate) + 2000; // someone messaged since
  if (leadReplied || newerActivity) continue;   // don't nudge
  out.push({ json: ctx });
}
return out;
